+    });
+  });
+
+  describe("extractFilesChanged — file path extraction from tool call blocks", () => {
+    // AC: @ui-session-stream ac-4
+    it("extracts file paths from Write tool calls", () => {
+      const blocks = [
+        {
+          type: "tool_call" as const,
+          toolName: "Write",
+          toolCallId: "1",
