+
+    // AC: @ui-session-stream ac-4
+    it("extracts file paths from Edit tool calls", () => {
+      const blocks = [
+        {
+          type: "tool_call" as const,
+          toolName: "Edit",
+          toolCallId: "1",
+          input: {
+            file_path: "/src/bar.ts",
