+	spec_context?: SessionSpecContext | null;
+	budget?: SessionBudget | null;
+}
+
+/**
+ * A single event from events.jsonl.
+ */
+export interface SessionEvent {
+	ts: number;
+	seq: number;
+	type: string;
+	session_id: string;
+	trace_id?: string;
+	data: unknown;
+}
