				{/if}

				<!-- Dependencies -->
				<div data-testid="task-dependencies">
					{#if task.depends_on.length > 0}
						<p class="text-sm font-medium mb-1">Dependencies:</p>
						<ul class="text-sm space-y-1">
							{#each task.depends_on as dep}
								<li>
